#include <iostream>


using namespace std;


bool prime(int n){if(n<2)return false;for(int d=2;1LL*d*d<=n;++d)if(n%d==0)return false;return true;}


int main(){int k;cin>>k;long long sum=0;int count=0;


for(int n=3;count<k;++n)if(prime(n)&&prime(n+2)){sum+=n;++count;}


cout<<sum<<'\n';}
